List<String> separateParenGroups(String parenString) {
  List<String> result = [];
  int depth = 0;
  String currentGroup = '';

  for (int i = 0; i < parenString.length; i++) {
    char c = parenString[i];

    if (c == '(' || c == '[' || c == '{') {
      // Start of a group, increment depth and add to currentGroup
      depth++;
      currentGroup += c;

      if (depth == 1) {
        // New group started
        result.add('');
      }
    } else if (c == ')' || c == ']' || c == '}') {
      // End of a group, decrement depth and check matching
      if (depth > 0 && isMatchingPair(currentGroup[currentGroup.length - 1], c)) {
        depth--;
        currentGroup = currentGroup.substring(0, currentGroup.length - 1);

        if (depth == 0) {
          // Group completed
          result[result.length - 1] += currentGroup + c;
          currentGroup = '';
        } else {
          // Continue the current group
          result[result.length - 1] += currentGroup + c;
        }
      } else {
        throw Exception('Mismatched brackets');
      }
    } else {
      // Regular character, just append it to the current group
      currentGroup += c;
    }
  }

  return result;
}

bool isMatchingPair(char open, char close) {
  switch (open) {
    case '(':
      return close == ')';
    case '[':
      return close == ']';
    case '{':
      return close == '}';
    default:
      return false;
  }
}
