void main() {
  // Test case 1
  List<String> result1 = separateParenGroups("( ) (( )) (( )( ))");
  print(result1);
  assert(result1.length == 3);
  assert(result1[0] == "()");
  assert(result1[1] == "(())");
  assert(result1[2] == "(()())");

