  while (i < musicString.length) {
    if (musicString[i] == '(') {
      // Handle parentheses
      int depth = 1;
      int j = i + 1;

      while (depth > 0 && j < musicString.length) {
        if (musicString[j] == '(') depth++;
        else if (musicString[j] == ')') depth--;

        if (depth == 0) {
          // End of the group, process it recursively
          final String subGroup = musicString.substring(i + 1, j);
          final List<int> parsedSubGroup = parseMusic(subGroup);

          for (int note in parsedSubGroup) {
            result.add(note);
          }

          i = j + 1;
          break;
