  if (numbers == null || numbers.isEmpty) return [];

  final result = <int>[];
  int i = 0;
  while (i < numbers.length) {
    final current = numbers[i];

    // Check if the current number is already in the result
    bool foundInResult = false;
    for (var j = 0; j < result.length; j++) {
      if (result[j] == current) {
        foundInResult = true;
        break;
      }
    }

    if (!foundInResult) {
      result.add(current);
      i++;
    } else {
