import 'dart:math';

bool triplesSumToZero(List<int> l) {
  if (l.length < 3) return false;

  for (int i = 0; i < l.length - 2; i++) {
    int a = l[i];

    // Skip duplicates to avoid duplicate triplets
    while (i < l.length - 2 && l[i + 1] == a) i++;

    int left = i + 1;
    int right = l.length - 1;

    while (left < right) {
      int b = l[left];
      int c = l[right];

      int sum = a + b + c;

      if (sum == 0) {
        return true;
      } else if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
}
```

