  if (lst.isEmpty) return [];

  int n = lst.length;
  for (int i = 0; i < n; i++) {
    int minIndex = i;
    for (int j = i + 1; j < n; j++) {
      if (lst[j] < lst[minIndex]) {
        minIndex = j;
      }
    }
    int temp = lst[i];
    lst[i] = lst[minIndex];
    lst[minIndex] = temp;
  }

  return lst;
}
