String antiShuffle(String s) {
  if (s.isEmpty) return '';

  List<String> words = [];
  String currentWord = '';
  int i = 0;

  while (i < s.length) {
    if (s[i] == ' ') {
      words.add(currentWord);
      currentWord = '';
      i++;
    } else if (s[i].isLetter) {
      // Add the character to the current word and shuffle it
      currentWord += s[i];
      i++;

      // If the next character is a space, we can sort the current word now
      if (i < s.length && s[i] == ' ') {
        currentWord = _shuffle(currentWord);
      }
    } else {
      // Handle non-letter characters by adding them directly
      currentWord += s[i];
      i++;
    }
  }

  // Add the last word
  words.add(currentWord);

  // Join all words with spaces
  return words.join(' ');
}

// Helper function to shuffle a string
String _shuffle(String str) {
  List<int> indices = List<int>.generate(str.length, (int index) => index);
  Random random = Random();

  for (int j = indices.length - 1; j > 0; j--) {
    int k = random.nextInt(j + 1);
    int temp = indices[j];
    indices[j] = indices[k];
    indices[k] = temp;
  }

  StringBuffer buffer = StringBuffer();
  for (int idx in indices) {
    buffer.write(str[idx]);
  }
  return buffer.toString();
}
