class PriorityQueue<T extends Comparable<T>> {
  final _queue = <T>[];

  void add(T element) => _queue.add(element);

  T removeFirst() {
    if (_queue.isEmpty) throw Exception('Empty priority queue');
    var index = 0;
    for (var i = 1; i < _queue.length; i++) {
      if (_queue[i].compareTo(_queue[index]) < 0) {
        index = i;
      }
    }
    final result = _queue[index];
    _queue.removeAt(index);
    return result;
  }

