    while (start < line.length && line[start].isEmpty) {
      start++;
    }

    int end = line.length - 1;
    while (end >= 0 && line[end].isEmpty) {
      end--;
    }

    if (start > end) {
      continue; // Skip empty lines
    }

    // Process the current line with leading/trailing whitespace removed
    String processedLine = line.substring(start, end + 1);

    // Replace multiple spaces between words with a single space
    processedLine = processedLine.replaceAll(RegExp(r' +' ), ' ');

    // Handle indentation of code blocks or sections
    bool isCodeBlock = false;
