        // Start of a new code block
        isCodeBlock = true;
        indentLevel = 0;

        // Find the number of spaces after the backticks to determine indentation level
        int firstNonBacktick = 3;
        while (firstNonBacktick < line.length && line[firstNonBacktick].isWhitespace) {
          firstNonBacktick++;
        }

        if (firstNonBacktick < line.length) {
